'use strict';

var uniform = require( '@stdlib/random/array/uniform' );
var logEach = require( '@stdlib/console/log-each' );
var Complex64Array = require( '@stdlib/array/complex64' );
var ccartesianProduct = require( './../lib' );

var opts = {
	'dtype': 'float32'
};
var M = 3;
var N = 2;
var xbuf = uniform( M * 2, -10, 10, opts );
var x = new Complex64Array( xbuf.buffer );
logEach( '%s', x );

var ybuf = uniform( N * 2, -10, 10, opts );
var y = new Complex64Array( ybuf.buffer );
logEach( '%s', y );

var out = new Complex64Array( M * N * 2 );

ccartesianProduct( 'row-major', M, N, x, 1, y, 1, out, 2 );
logEach( '%s', out );
